const F=Finance,$=s=>document.querySelector(s),money=n=>'₦'+Math.round(n).toLocaleString('en-NG'),esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const date=d=>new Date(d+'T12:00:00').toLocaleDateString('en-NG',{day:'numeric',month:'short'}),iso=()=>{const d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;};
function fresh(){const d=new Date();d.setDate(d.getDate()+30);return {version:1,name:'',school:'',nextDate:`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`,budgets:Object.fromEntries(F.categories.map(c=>[c,0])),transactions:[],goals:[]};}
let state=fresh(),storageOk=true;try{const raw=localStorage.getItem('kasuapay-v1');if(raw){const s=JSON.parse(raw);if(s.version!==1||!Array.isArray(s.transactions)||!Array.isArray(s.goals)||!s.budgets)throw Error();state=s;}}catch{storageOk=false;}
let page='overview',formKind='',filter='',query='';const icons={Food:'◔',Transport:'↗',Data:'⌁',Academics:'▧',Emergency:'✚',Flexible:'✦'};
function save(){try{localStorage.setItem('kasuapay-v1',JSON.stringify(state));storageOk=true;}catch{storageOk=false;toast('Storage unavailable. Keep this tab open to retain changes.');}render();}
let toastTimer;function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3500);}
function budgetRows(){return `<div class="budget-list">${F.categories.map(c=>{const used=F.spent(state,c),limit=state.budgets[c]||0,ratio=limit?used/limit*100:used?100:0;return `<div class="budget-row"><span class="category-icon ${c}">${icons[c]}</span><div><div class="row-label"><b>${c}</b><small><span style="color:${used>limit?'#bd6448':'#536647'}">${money(used)}</span> / ${money(limit)}</small></div><div class="track" role="progressbar" aria-label="${c} spending" aria-valuenow="${Math.min(100,Math.round(ratio))}" aria-valuemin="0" aria-valuemax="100"><div class="fill ${used>limit?'over':''}" style="width:${Math.min(100,ratio)}%"></div></div></div></div>`;}).join('')}</div>`;}
function goalsMarkup(){return state.goals.length?state.goals.map(g=>`<article class="goal-item"><div class="goal-top"><span class="goal-icon">${g.icon||'◎'}</span><div><h3>${esc(g.name)}</h3><small>${g.saved>=g.target?'Goal reached!':g.due?'Target: '+date(g.due):'One small step at a time'}</small></div><button data-action="contribute" data-id="${esc(g.id)}" aria-label="Contribute to ${esc(g.name)}">+</button></div><div class="goal-values"><b>${money(g.saved)} <span>of ${money(g.target)}</span></b><span>${Math.floor(g.saved/g.target*100)}%</span></div><div class="track"><div class="fill" style="width:${Math.min(100,g.saved/g.target*100)}%"></div></div></article>`).join(''):'<div class="empty"><strong>Something worth saving for?</strong>From project materials to your next laptop,<br>start with a goal and a little at a time.</div>';}
function transactionsMarkup(limit){let list=state.transactions.filter(t=>(!filter||t.type===filter)&&(!query||`${t.note} ${t.category}`.toLowerCase().includes(query.toLowerCase()))).slice().reverse();if(limit)list=list.slice(0,limit);return list.length?`<div style="overflow-x:auto"><table class="table"><thead><tr><th>TRANSACTION</th><th class="optional">CATEGORY</th><th>DATE</th><th>AMOUNT</th></tr></thead><tbody>${list.map(t=>`<tr><td><b>${esc(t.note)}</b><small>${t.type==='income'?'↙ Money in':'↗ Money out'}${page==='activity'?` · <button class="text-button" style="font-size:9px" data-action="delete" data-id="${t.id}">Remove</button>`:''}</small></td><td class="optional"><span class="category-tag">${esc(t.category)}</span></td><td>${date(t.date)}</td><td class="${t.type==='income'?'positive':'negative'}"><b>${t.type==='income'?'+':'−'}${money(t.amount)}</b></td></tr>`).join('')}</tbody></table></div>`:'<div class="empty"><strong>No transactions yet</strong>Add your allowance or record an expense to see it here.</div>';}
function render(){page=['overview','budget','goals','activity'].includes(location.hash.slice(1))?location.hash.slice(1):'overview';const labels={overview:'Overview',budget:'My budget',goals:'Savings goals',activity:'Transactions'};document.querySelectorAll('[data-page]').forEach(a=>{const active=a.dataset.page===page;a.classList.toggle('active',active);if(active)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});$('#page-label').textContent=labels[page];$('#profile-name').textContent=state.name||'Your account';$('#avatar').textContent=(state.name||'Y').charAt(0).toUpperCase();$('#today').textContent=new Date().toLocaleDateString('en-NG',{weekday:'long',day:'numeric',month:'long',year:'numeric'});$('#greeting').textContent=page==='overview'?(state.name?`Looking good, ${state.name.split(' ')[0]}.`:'A fresh start for your money.'):labels[page];$('#subtitle').textContent={overview:'A little planning. A lot more peace of mind.',budget:'Give every naira a place in your campus life.',goals:'Big plans begin with small savings.',activity:'Keep an eye on the little things. They add up.'}[page];
const b=F.balance(state),safe=F.safe(state),saved=state.goals.reduce((n,g)=>n+g.saved,0),totalSpent=state.transactions.filter(t=>t.type==='expense').reduce((n,t)=>n+t.amount,0);const warning=!storageOk?'<div class="storage-warning">Browser storage is unavailable or could not be read. Changes may only last for this session.</div>':'';let html=warning;
if(page==='overview'){html+=!state.name?`<div class="welcome"><div><h3>Welcome to your student money space ✦</h3><p>Set up your profile, add an allowance, and give your money a plan.</p></div><button class="button" data-action="profile">Let’s get you started ↗</button></div>`:'';html+=`<section class="summary-grid" aria-label="Money summary"><article class="card balance-card"><div class="card-label">◉ Available balance</div><div class="metric">${money(b)}</div><div class="card-foot">Your money after savings are set aside</div><div class="balance-bottom"><span class="card-foot">${state.transactions.length?'Making every naira count':'Ready when you are'}</span><button data-action="expense">↗ Record expense</button></div></article><article class="card safe-card"><div class="card-label"><span class="tiny-icon">↗</span> Safe to spend today</div><div class="metric">${money(safe.daily)} <small>/ day</small></div><div class="card-foot">${money(safe.available)} over ${safe.days} day${safe.days===1?'':'s'}<br>Emergency reserve and savings protected.</div><div style="margin-top:18px"><button class="text-button" data-action="planner">Next income: ${date(state.nextDate)} ↗</button></div></article><article class="card"><div class="card-label"><span class="tiny-icon">◎</span> Total saved</div><div class="metric">${money(saved)}</div><div class="card-foot">Across ${state.goals.length} saving${state.goals.length===1?'':'s'} goal${state.goals.length===1?'':'s'}</div><div style="margin-top:24px"><span class="badge">✦ Your future self says thanks</span></div></article></section><div class="dashboard-grid"><section class="card"><div class="section-heading"><div><h2>Your money, with a plan</h2><small>Spending across your budget categories</small></div><button class="text-button" data-action="allocate">Edit budget ↗</button></div>${budgetRows()}<div class="budget-footer"><span>Total spent <b>${money(totalSpent)}</b></span><a href="#budget">View budget →</a></div></section><section class="card"><div class="section-heading"><div><h2>A little closer to your goals</h2><small>Small amounts. Meaningful progress.</small></div><button class="text-button" data-action="goal">＋ New goal</button></div>${goalsMarkup()}<div class="goal-tip">✦ Try setting aside a small amount whenever money comes in. Consistency makes the difference.</div></section></div><section class="card transactions-card"><div class="section-heading"><div><h2>Your latest activity</h2><small>A clearer picture of where your money goes</small></div><a class="text-button" href="#activity">View all →</a></div>${transactionsMarkup(5)}</section>`;}
if(page==='budget'){const over=F.categories.filter(c=>F.spent(state,c)>(state.budgets[c]||0));html+=`<section class="card"><div class="section-heading"><div><h2>Your budget allocations</h2><small>Category limits cover all recorded spending in this plan</small></div><button class="button primary" data-action="allocate">Edit allocation</button></div>${budgetRows()}<div class="insight">${over.length?'Heads up: '+over.map(esc).join(', ')+' spending is above your planned limit. Review your allocations before your next purchase.':'Your plan is yours to shape. Allocate money around food, transport, data, academics, and the things that matter to you.'}</div></section><section class="card transactions-card"><div class="section-heading"><h2>Your allowance timeline</h2><button class="text-button" data-action="planner">Update date ↗</button></div><p class="hint">Next expected income: <b>${date(state.nextDate)}</b>. Your daily estimate divides ${money(safe.available)} by ${safe.days} days. Savings and your remaining emergency allocation are excluded. This is an estimate based on your entries; unrecorded spending and future income are not included.</p></section>`;}
if(page==='goals')html+=`<section class="card"><div class="section-heading"><div><h2>Make room for what’s next</h2><small>Set money aside for your academic and personal goals</small></div><button class="button primary" data-action="goal">＋ Create goal</button></div><div class="goals-grid">${goalsMarkup()}</div><p class="hint">Contributions move money from your available balance into a goal. These are planning records on this device; no funds are held or transferred.</p></section>`;
if(page==='activity')html+=`<section class="card"><div class="section-heading"><h2>Money in. Money out.</h2><button class="button primary" data-action="expense">＋ Add expense</button></div><div class="toolbar"><input id="search" type="search" placeholder="Search transactions…" aria-label="Search transactions" value="${esc(query)}"><select id="filter" aria-label="Filter transaction type"><option value="">All transactions</option><option value="income" ${filter==='income'?'selected':''}>Income</option><option value="expense" ${filter==='expense'?'selected':''}>Expenses</option></select><button class="button" data-action="export">Export CSV ↓</button></div><div id="transaction-results">${transactionsMarkup()}</div></section>`;$('#app').innerHTML=html;}
function field(label,name,type='text',value='',extra=''){return `<label class="field">${label}<input name="${name}" type="${type}" value="${esc(value)}" ${extra}></label>`;}
function openForm(kind,id){formKind=kind;$('#modal-form').dataset.id=id||'';$('#form-error').textContent='';let title='',body='',submit='Save';const amount=(label='Amount (₦)')=>field(label,'amount','number','','required min="1" step="1" max="100000000"');
if(kind==='profile'){title='Make yourself at home';body='<p class="hint">Your details stay in this browser. Add just a first name if you prefer.</p>'+field('Your name','name','text',state.name,'required maxlength="40" autocomplete="given-name"')+field('University (optional)','school','text',state.school,'maxlength="100"')+field('When do you expect your next income?','nextDate','date',state.nextDate,`required min="${iso()}"`);submit='Save my profile';}
if(kind==='income'){title='A little breathing room';body=amount()+field('Where is it from?','note','text','','required maxlength="70" placeholder="e.g. Monthly allowance"')+field('Date received','date','date',iso(),`required max="${iso()}"`)+'<p class="hint">After adding income, set your budget to give it a plan.</p>';submit='Add income';}
if(kind==='expense'){title='Record an expense';body=amount()+field('What was it for?','note','text','','required maxlength="70" placeholder="e.g. Lunch at the cafeteria"')+`<label class="field">Category<select name="category">${F.categories.map(c=>`<option>${c}</option>`).join('')}</select></label>`+field('Date','date','date',iso(),`required max="${iso()}"`);submit='Record expense';}
if(kind==='goal'){title='What are you saving for?';body=field('Goal name','name','text','','required maxlength="50" placeholder="e.g. My next laptop"')+field('Target amount (₦)','target','number','','required min="1" step="1" max="100000000"')+field('Target date (optional)','due','date','',`min="${iso()}"`);submit='Create goal';}
if(kind==='contribute'){const g=state.goals.find(g=>g.id===id);if(!g)return;title='A step closer';body=`<p class="hint">Add to <b>${esc(g.name)}</b>. Available balance: ${money(F.balance(state))}.</p>`+amount()+'<p class="hint">This contribution is set aside from your balance and protected from your safe-to-spend estimate.</p>';submit='Set money aside';}
if(kind==='allocate'){title='Give your money a plan';const income=state.transactions.filter(t=>t.type==='income').reduce((n,t)=>n+t.amount,0)-state.goals.reduce((n,g)=>n+g.saved,0);body=`<p class="hint">You have ${money(Math.max(0,income))} available for total category limits, including spending already recorded. Choose amounts that fit your needs.</p><button type="button" class="button" data-action="suggest">Suggest an allocation</button><div class="allocation-fields">${F.categories.map(c=>field(c,c,'number',state.budgets[c]||0,'required min="0" step="1" max="100000000"')).join('')}</div><p class="hint">Emergency money is reserved from your daily estimate. Edit these limits as your circumstances change.</p>`;submit='Save allocation';}
if(kind==='planner'){title='Plan your next allowance';body=field('Next expected income date','nextDate','date',state.nextDate,`required min="${iso()}"`)+'<p class="hint">We spread your available funds across the remaining days. Future income is only counted when you record it.</p>';submit='Update plan';}
$('#modal-title').textContent=title;$('#modal-body').innerHTML=body;$('#modal-submit').textContent=submit;$('#modal').showModal();}
$('#modal-form').addEventListener('submit',e=>{e.preventDefault();const data=Object.fromEntries(new FormData(e.target)),amount=Number(data.amount);try{if(['income','expense','contribute'].includes(formKind)&&(!Number.isSafeInteger(amount)||amount<=0))throw Error('Enter a positive whole-naira amount.');if(formKind==='profile'){state.name=data.name.trim();if(!state.name)throw Error('Please enter your name.');state.school=data.school.trim();state.nextDate=data.nextDate;}
if(formKind==='income'||formKind==='expense'){if(!data.note.trim())throw Error('Add a short description.');if(formKind==='expense'&&amount>F.balance(state))throw Error('This expense is larger than your available balance. Record missing income first.');state.transactions.push({id:crypto.randomUUID(),type:formKind,amount,note:data.note.trim(),category:formKind==='income'?'Income':data.category,date:data.date});}
if(formKind==='goal'){const target=Number(data.target);if(!Number.isSafeInteger(target)||target<=0||!data.name.trim())throw Error('Enter a goal name and positive whole-naira target.');state.goals.push({id:crypto.randomUUID(),name:data.name.trim(),target,saved:0,due:data.due,icon:'◎'});}
if(formKind==='contribute'){if(amount>F.balance(state))throw Error('Add income first — your contribution exceeds your available balance.');const g=state.goals.find(g=>g.id===e.target.dataset.id);if(!g)throw Error('Goal no longer exists.');g.saved+=amount;}
if(formKind==='allocate'){const values=F.categories.map(c=>Number(data[c]));if(values.some(v=>!Number.isSafeInteger(v)||v<0))throw Error('Use zero or a positive whole-naira amount for each category.');const pool=state.transactions.filter(t=>t.type==='income').reduce((n,t)=>n+t.amount,0)-state.goals.reduce((n,g)=>n+g.saved,0);if(values.reduce((a,b)=>a+b,0)>Math.max(0,pool))throw Error('Your allocation exceeds income remaining after savings. Reduce a category amount.');state.budgets=Object.fromEntries(F.categories.map((c,i)=>[c,values[i]]));}
if(formKind==='planner')state.nextDate=data.nextDate;$('#modal').close();save();toast(formKind==='income'?'Income added. Give it a plan in My budget.':'Saved. One step closer to a clearer money plan.');}catch(err){$('#form-error').textContent=err.message;}});
document.addEventListener('click',e=>{const button=e.target.closest('[data-action]');if(!button)return;const a=button.dataset.action;if(a==='close')return $('#modal').close();if(a==='suggest'){const pool=Math.max(0,state.transactions.filter(t=>t.type==='income').reduce((n,t)=>n+t.amount,0)-state.goals.reduce((n,g)=>n+g.saved,0));let rest=pool;F.categories.forEach((c,i)=>{const v=i===F.categories.length-1?rest:Math.floor(pool*F.weights[i]);$('#modal-form').elements[c].value=v;rest-=v;});return;}if(a==='delete'){const t=state.transactions.find(t=>t.id===button.dataset.id);if(!t)return;if(t.type==='income'&&F.balance(state)-t.amount<0)return toast('This income supports spending or savings and cannot be removed.');if(!confirm('Remove this transaction? Your balance will be recalculated.'))return;state.transactions=state.transactions.filter(t=>t.id!==button.dataset.id);save();return toast('Transaction removed. Review your budget allocations.');}if(a==='export'){const rows=[['Date','Type','Description','Category','Amount NGN'],...state.transactions.map(t=>[t.date,t.type,t.note,t.category,t.amount])];const csv=rows.map(row=>row.map(v=>'"'+String(v).replace(/^[=+@-]/,"'$&").replace(/"/g,'""')+'"').join(',')).join('\r\n');const url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'})),link=document.createElement('a');link.href=url;link.download='kasuapay-transactions.csv';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);return;}openForm(a,button.dataset.id);});
document.addEventListener('input',e=>{if(e.target.id==='search'){query=e.target.value;$('#transaction-results').innerHTML=transactionsMarkup();}});document.addEventListener('change',e=>{if(e.target.id==='filter'){filter=e.target.value;$('#transaction-results').innerHTML=transactionsMarkup();}});window.addEventListener('hashchange',render);render();
